// Vercel Node.js serverless function — adapts the pre-built SSR bundle
// to Vercel's (req, res) interface. The bundle is generated by `npm run build`.
const { default: server } = await import('../dist/server/_ssr/index.mjs');

export default async function handler(req, res) {
  const host = req.headers['x-forwarded-host'] || req.headers.host || 'localhost';
  const proto = req.headers['x-forwarded-proto'] || 'https';
  const url = new URL(req.url ?? '/', `${proto}://${host}`);

  const headers = new Headers();
  for (const [key, value] of Object.entries(req.headers)) {
    if (value == null) continue;
    if (Array.isArray(value)) {
      for (const v of value) headers.append(key, v);
    } else {
      headers.set(key, value);
    }
  }

  let body = null;
  if (req.method !== 'GET' && req.method !== 'HEAD') {
    const chunks = [];
    await new Promise((resolve, reject) => {
      req.on('data', (c) => chunks.push(c));
      req.on('end', resolve);
      req.on('error', reject);
    });
    if (chunks.length > 0) body = Buffer.concat(chunks);
  }

  const requestInit = { method: req.method, headers, body };
  if (body) requestInit.duplex = 'half';
  const request = new Request(url.href, requestInit);

  const response = await server.fetch(request, {}, {});

  res.statusCode = response.status;

  for (const [key, value] of response.headers.entries()) {
    const lower = key.toLowerCase();
    if (lower === 'transfer-encoding' || lower === 'connection') continue;
    res.setHeader(key, value);
  }

  if (response.body) {
    const reader = response.body.getReader();
    try {
      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        if (!res.write(value)) {
          await new Promise((resolve) => res.once('drain', resolve));
        }
      }
    } finally {
      reader.releaseLock();
    }
  }

  res.end();
}
